362	                    claim.setRef(rs.getString("ext_ref"));
363	                    claim.setVoidReason(rs.getString("void_reason"));
364	                    claim.setSettleBatch((Integer) rs.getObject("settle_batch", Integer.class));
365	                    latest.put(claim.getId(), claim);
366	                    listed.put(claim.getId(), rs.getLong("listed"));
367	                }, sheetId, Date.valueOf(day));
368	        for (Claim claim : latest.values()) {
369	            if (claim.getCorrects() == null) continue;
370	            latest.values().stream()
371	                    .filter((c) -> c.getPersonId() == claim.getPersonId() && claim.getCorrects().equals(c.getNumber()))
372	                    .findFirst().ifPresent((c) -> claim.setCorrectedDate(c.getDate()));
373	        }
374	        return latest.values().stream()
375	                .sorted(java.util.Comparator.comparing((Claim c) -> listed.get(c.getId())).thenComparing(Claim::getId)
376	                        .reversed())
377	                .toList();
378	    }
379	}
