496	    /**
497	     * Swap the person with the one next to them in the sheet's list: above ({@code up}) or below.
498	     * Returns their new position, counting from 1; null when there is no one there (the top row
499	     * cannot move up nor the bottom row down) and nothing is written.
500	     */
501	    public Integer move(Person person, boolean up) {
502	        List<long[]> list = jdbc.query("SELECT id, list_pos FROM person WHERE sheet_id = ? AND merged_into IS NULL"
503	                + " ORDER BY list_pos, id", (rs, n) -> new long[] { rs.getLong("id"), rs.getLong("list_pos") },
504	                person.getSheetId());
505	        int at = -1;
506	        for (int i = 0; i < list.size(); i++) if (list.get(i)[0] == person.getId()) at = i;
507	        int to = up ? at - 1 : at + 1;
508	        if (at < 0 || to < 0 || to >= list.size()) return null;
509	        long[] mine = list.get(at), theirs = list.get(to);
510	        // Positions may tie (never in practice): give them distinct ones in the order listed.
511	        long minePos = mine[1], theirsPos = theirs[1];
512	        if (minePos == theirsPos) {
513	            for (int i = 0; i < list.size(); i++) {
514	                jdbc.update("UPDATE person SET list_pos = ? WHERE id = ?", i + 1L, list.get(i)[0]);
515	            }
516	            minePos = at + 1L;
517	            theirsPos = to + 1L;
518	        }
519	        jdbc.update("UPDATE person SET list_pos = ? WHERE id = ?", theirsPos, mine[0]);
520	        jdbc.update("UPDATE person SET list_pos = ? WHERE id = ?", minePos, theirs[0]);
521	        return to + 1;
522	    }
