538	    /**
539	     * Merge {@code from} into {@code into}: {@code from}'s name and aliases become {@code into}'s aliases;
540	     * their patrons are added to {@code into}'s (not {@code into} themselves, no repeats); anyone naming
541	     * {@code from} as patron names {@code into} instead (no repeats). {@code from}'s holds, watchers and
542	     * contact are dropped, and they are marked merged, leaving the list.
543	     */
544	    public void merge(Person from, Person into) {
545	        String sheetId = from.getSheetId();
546	        jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
547	        addAlias(into, from.getName());
548	        for (String alias : from.getAliases()) addAlias(into, alias);
549	        // Their own patrons go to the other, not the other themselves, nor one the other already names.
550	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND person_id = ? AND (patron_id = ?"
551	                + " OR patron_id IN (SELECT p.patron_id FROM person_patron p WHERE p.person_id = ?))",
552	                sheetId, from.getId(), into.getId(), into.getId());
553	        jdbc.update("UPDATE person_patron SET person_id = ? WHERE sheet_id = ? AND person_id = ?",
554	                into.getId(), sheetId, from.getId());
555	        // Those naming them name the other instead: not the other themselves, nor anyone already naming the other.
556	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND patron_id = ? AND (person_id = ?"
557	                + " OR person_id IN (SELECT p.person_id FROM person_patron p WHERE p.patron_id = ?))",
558	                sheetId, from.getId(), into.getId(), into.getId());
559	        jdbc.update("UPDATE person_patron SET patron_id = ? WHERE sheet_id = ? AND patron_id = ?",
560	                into.getId(), sheetId, from.getId());
561	        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
562	        jdbc.update("DELETE FROM person_watch WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
563	        jdbc.update("UPDATE person SET contact = NULL, merged_into = ?, merged_on = (SELECT today FROM sheet WHERE id = ?),"
564	                + " version = version + 1 WHERE id = ? AND sheet_id = ?", into.getId(), sheetId, from.getId(), sheetId);
565	        jdbc.update("UPDATE person SET version = version + 1 WHERE id = ? AND sheet_id = ?", into.getId(), sheetId);
566	    }
