568	    /**
569	     * Move the person to another sheet, with their grades (and from-dates), terms, contact and aliases,
570	     * as added there on that sheet's today: their statements start again at none and they are not
571	     * retired. Patron links either way, pool memberships, watches and holds are dropped. Their claims
572	     * are moved by the caller.
573	     */
574	    public void transfer(Person person, String toSheet) {
575	        long id = person.getId();
576	        jdbc.update("DELETE FROM person_patron WHERE person_id = ? OR patron_id = ?", id, id);
577	        jdbc.update("DELETE FROM pool_member WHERE person_id = ?", id);
578	        jdbc.update("DELETE FROM person_watch WHERE person_id = ?", id);
579	        jdbc.update("DELETE FROM person_hold WHERE person_id = ?", id);
580	        jdbc.update("DELETE FROM person_statement WHERE person_id = ?", id);
581	        jdbc.update("DELETE FROM person_statement_history WHERE person_id = ?", id);
582	        jdbc.update("DELETE FROM person_retirement WHERE person_id = ?", id);
583	        jdbc.update("DELETE FROM person_past_retirement WHERE person_id = ?", id);
584	        jdbc.update("DELETE FROM person_grade_history WHERE person_id = ?", id);
585	        jdbc.update("DELETE FROM person_terms_history WHERE person_id = ?", id);
586	        jdbc.update("UPDATE person_grade SET sheet_id = ? WHERE person_id = ?", toSheet, id);
587	        jdbc.update("UPDATE person_alias SET sheet_id = ?, added_on = (SELECT today FROM sheet WHERE id = ?)"
588	                + " WHERE person_id = ?", toSheet, toSheet, id);
589	        jdbc.update("UPDATE person SET sheet_id = ?, statement_count = 0, stated_total = NULL, statement_date = NULL,"
590	                + " retired_from = NULL, added_on = (SELECT today FROM sheet WHERE id = ?), list_pos = " + END_OF_LIST + ","
591	                + " origin_sheet = ?, version = version + 1 WHERE id = ?", toSheet, toSheet, toSheet, person.getSheetId(), id);
592	        Person moved = find(toSheet, id);
593	        gradeHistory(moved, null, moved.getGrade());
594	        termsHistory(moved);
595	        moved.getDatedGrades().forEach((from, grade) -> gradeHistory(moved, from, grade));
596	    }
