776	     * Insert a new person (assigning its id) or update an existing one, raising its version. False
777	     * when the stored person is no longer at the version it was loaded at: nothing is written.
778	     */
779	    public boolean save(Person person) {
780	        if (person.getId() != null) {
781	            List<String> storedGrade = jdbc.queryForList("SELECT grade FROM person WHERE id = ? AND sheet_id = ?",
782	                    String.class, person.getId(), person.getSheetId());
783	            List<Integer> storedTerms = jdbc.query("SELECT terms FROM person WHERE id = ? AND sheet_id = ?",
784	                    (rs, n) -> rs.getObject("terms", Integer.class), person.getId(), person.getSheetId());
785	            Map<LocalDate, String> storedDated = new HashMap<>();
786	            jdbc.query("SELECT from_date, grade FROM person_grade WHERE sheet_id = ? AND person_id = ?",
787	                    (rs) -> {
788	                        storedDated.put(rs.getObject("from_date", LocalDate.class), rs.getString("grade"));
789	                    }, person.getSheetId(), person.getId());
790	            int updated = jdbc.update("UPDATE person SET name = ?, grade = ?, terms = ?, contact = ?, version = version + 1"
791	                    + " WHERE id = ? AND sheet_id = ? AND version = ?",
792	                    person.getName(), person.getGrade(), person.getTerms(), person.getContact(), person.getId(), person.getSheetId(),
793	                    person.getVersion());
794	            if (updated == 0) return false;
795	            person.setVersion(person.getVersion() + 1);
796	            saveGrades(person);
797	            if (storedGrade.isEmpty() || !storedGrade.get(0).equals(person.getGrade())) {
798	                gradeHistory(person, null, person.getGrade());
799	            }
800	            if (storedTerms.isEmpty() || !Objects.equals(storedTerms.get(0), person.getTerms())) termsHistory(person);
801	            person.getDatedGrades().forEach((from, grade) -> {
802	                if (!grade.equals(storedDated.get(from))) gradeHistory(person, from, grade);
803	            });
804	            return true;
805	        }
806	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
807	        jdbc.update(con -> {
808	            PreparedStatement ps = con.prepareStatement(
809	                    "INSERT INTO person (sheet_id, name, grade, terms, contact, added_on, list_pos) VALUES (?, ?, ?, ?, ?,"
810	                            + " (SELECT today FROM sheet WHERE id = ?), " + END_OF_LIST + ")",
811	                    Statement.RETURN_GENERATED_KEYS);
812	            ps.setString(1, person.getSheetId());
813	            ps.setString(2, person.getName());
814	            ps.setString(3, person.getGrade());
815	            ps.setObject(4, person.getTerms(), java.sql.Types.INTEGER);
816	            ps.setString(5, person.getContact());
817	            ps.setString(6, person.getSheetId());
818	            ps.setString(7, person.getSheetId());
819	            return ps;
820	        }, keys);
821	        person.setId(keys.getKey().longValue());
822	        person.setAddedOn(jdbc.queryForObject("SELECT added_on FROM person WHERE id = ?", LocalDate.class, person.getId()));
823	        saveGrades(person);
824	        gradeHistory(person, null, person.getGrade());
825	        termsHistory(person);
826	        person.getDatedGrades().forEach((from, grade) -> gradeHistory(person, from, grade));
827	        return true;
828	    }
829	
830	    /** Keeps a grade given to the person (from {@code from}; null: their first grade) in its history, with the sheet's today now. */
831	    private void gradeHistory(Person person, LocalDate from, String grade) {
832	        jdbc.update("INSERT INTO person_grade_history (sheet_id, person_id, from_date, grade, set_on)"
833	                + " VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
834	                person.getSheetId(), person.getId(), from == null ? null : Date.valueOf(from), grade, person.getSheetId());
835	    }
836	
837	    /** Keeps the person's terms (null: none) in their history, with the sheet's today now. */
838	    private void termsHistory(Person person) {
839	        jdbc.update("INSERT INTO person_terms_history (sheet_id, person_id, terms, set_on)"
840	                + " VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
841	                person.getSheetId(), person.getId(), person.getTerms(), person.getSheetId());
842	    }
843	
844	    /**
845	     * The person as they stood at the end of {@code day}: their grades, terms, holds, retirement, statements,
846	     * aliases and patrons as given while the sheet's today was on or before it; the rest as they are now.
847	     */
848	    public Person asOf(Person person, LocalDate day) {
849	        Date on = Date.valueOf(day);
850	        String[] first = { person.getGrade() };
851	        Map<LocalDate, String> dated = new HashMap<>();
852	        jdbc.query("SELECT from_date, grade FROM person_grade_history WHERE sheet_id = ? AND person_id = ?"
853	                + " AND set_on <= ? ORDER BY id", (rs) -> {
854	                    LocalDate from = rs.getObject("from_date", LocalDate.class);
855	                    if (from == null) first[0] = rs.getString("grade");
856	                    else dated.put(from, rs.getString("grade"));
857	                }, person.getSheetId(), person.getId(), on);
858	        Person then = new Person(person.getId(), person.getSheetId(), person.getName(), first[0], person.getVersion());
859	        List<Integer> terms = jdbc.query("SELECT terms FROM person_terms_history WHERE sheet_id = ? AND person_id = ?"
860	                + " AND set_on <= ? ORDER BY id DESC LIMIT 1", (rs, n) -> rs.getObject("terms", Integer.class),
861	                person.getSheetId(), person.getId(), on);
862	        then.setTerms(terms.isEmpty() ? null : terms.get(0));
863	        then.setContact(person.getContact());
864	        then.getAliases().addAll(jdbc.queryForList("SELECT alias FROM person_alias WHERE sheet_id = ? AND person_id = ?"
865	                + " AND (added_on IS NULL OR added_on <= ?) ORDER BY id", String.class, person.getSheetId(), person.getId(), on));
866	        then.setAddedOn(person.getAddedOn());
867	        then.setStatements(0, null, null);
868	        jdbc.query("SELECT statement_count, stated_total, statement_date FROM person_statement_history"
869	                + " WHERE sheet_id = ? AND person_id = ? AND set_on <= ? ORDER BY id DESC LIMIT 1", (rs) -> {
870	                    then.setStatements(rs.getInt("statement_count"), rs.getString("stated_total"),
871	                            rs.getObject("statement_date", LocalDate.class));
872	                }, person.getSheetId(), person.getId(), on);
873	        dated.forEach((from, grade) -> then.setGradeFrom(grade, from));
874	        jdbc.query("SELECT from_date, to_date FROM person_hold WHERE sheet_id = ? AND person_id = ?"
875	                + " AND (made_on IS NULL OR made_on <= ?) ORDER BY id", (rs) -> {
876	                    then.getHolds().add(hold(rs));
877	                }, person.getSheetId(), person.getId(), on);
878	        List<LocalDate> retired = jdbc.query("SELECT from_date FROM person_retirement WHERE sheet_id = ? AND person_id = ?"
879	                + " AND set_on <= ? ORDER BY id DESC LIMIT 1", (rs, n) -> rs.getObject("from_date", LocalDate.class),
880	                person.getSheetId(), person.getId(), on);
881	        then.setRetiredFrom(retired.isEmpty() ? null : retired.get(0));
882	        then.getPastRetirements().addAll(person.getPastRetirements().stream().filter((r) -> !r.to().isAfter(day)).toList());
883	        then.getPatronIds().addAll(jdbc.queryForList("SELECT patron_id FROM person_patron WHERE sheet_id = ?"
884	                + " AND person_id = ? AND (added_on IS NULL OR added_on <= ?) ORDER BY named_seq NULLS FIRST, patron_id", Long.class,
885	                person.getSheetId(), person.getId(), on));
886	        return then;
887	    }
