public class HandleStewardOnly {
    public void handle(@Parameter StewardOnlyException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.FORBIDDEN));
    }
}
