  const settings = useSettings(sheetId);
  const [input, setInput] = useState('');
  const [error, setError] = useState('');
  const [user] = useUser();

  const once = useOnce();
  const save = useMutation({
    mutationFn: (today: string) =>
      postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { today }, user),
    onSuccess: (updated) => {
      queryClient.setQueryData(sheetKey(sheetId), updated);
      void queryClient.invalidateQueries({
        queryKey: ['sheet', sheetId],
        predicate: (q) => q.queryKey[2] !== 'info',
      });
    },
    onError: () => setError('That date could not be set as today.'),
  });

  const archive = useMutation({
    mutationFn: () => postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/archive`, {}, user),
    onSuccess: (updated) => queryClient.setQueryData(sheetKey(sheetId), updated),
    onError: () => setError('The sheet could not be archived.'),
  });

  const archiveSheet = () => {
    setError('');
    once((done) => archive.mutate(undefined, { onSettled: done }));
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const today = input.trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      setError('Choose a date for today.');
      return;
    }
    once((done) => save.mutate(today, { onSettled: done }));
  };

  return (
    <form onSubmit={submit} data-testid="sheet-today-form">
      Today: <strong data-testid="sheet-today">{sheet.data?.today ?? ''}</strong>{' '}
      <label>
        Set today{' '}
        <input
          type="date"
          data-testid="sheet-today-input"
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set
      </button>{' '}
      Archived: <strong data-testid="sheet-archived">{sheet.data ? (sheet.data.archived ? 'yes' : 'no') : ''}</strong>{' '}
      <button type="button" data-testid="sheet-archive" onClick={archiveSheet} disabled={archive.isPending}>
        Archive sheet
      </button>{' '}
      Parent: <strong data-testid="sheet-parent">{settings.data?.parent ?? ''}</strong>
      {(error || sheet.isError) && (
        <p role="alert" data-testid="sheet-error">
          {error || 'The sheet could not be read.'}
        </p>
      )}
    </form>
  );
}

export const contribution = SheetBody.fill({ order: -100, Component: SheetToday });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type Sheet = { id: string; today: string; archived: boolean };

export const sheetKey = (sheetId: string) => ['sheet', sheetId, 'info'] as const;

/** The loaded sheet: its id, its today (yyyy-MM-dd) and whether a steward has archived it. */
export function useSheet(sheetId: string) {
  return useQuery({
    queryKey: sheetKey(sheetId),
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`),
  });
}

/**
 * The sheet's today. Every date-dependent decision and every default date on the screen uses this,
 * never the real clock (`new Date()`); '' until the sheet has been read.
 */
export function useSheetToday(sheetId: string): string {
  return useSheet(sheetId).data?.today ?? '';
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { PersonHead, PersonRow } from '../../slots/defs/personRow';
import type { Person } from '../people/people';
import { useUser } from '../session/session';
import { useRowError } from '../people/rowError';

function TransferHead() {
  return <th>Transfer</th>;
}

function OriginHead() {
  return <th>From sheet</th>;
}

// The sheet this person was transferred from (empty for anyone never transferred).
function PersonOrigin({ person }: { sheetId: string; person: Person }) {
  return <td data-testid="person-origin">{person.origin}</td>;
}

// An entry for another sheet's id and a button that transfers this person there (a steward): they
// arrive with their grades, terms, contact, aliases and claims, and leave this sheet's list.
function PersonTransfer({ sheetId, person }: { sheetId: string; person: Person }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [to, setTo] = useState('');
  const [error, setError] = useRowError(person.id, 'transfer');
  const once = useOnce();
  const transfer = useMutation({
    mutationFn: (toSheet: string) =>
      postJson<Person>(
        `/api/sheets/${encodeURIComponent(sheetId)}/people/${encodeURIComponent(person.id)}/transfer`,
        { toSheet },
        user,
      ),
    onSuccess: async (_person, toSheet) => {
      await queryClient.invalidateQueries({ queryKey: ['sheet', toSheet.trim()] });
      await queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
    },
    onError: () => setError('That person could not be transferred.'),
  });

  const submit = () => {
    setError('');
    once((done) => transfer.mutate(to, { onSettled: done }));
  };

  return (
    <td>
      <input
        data-testid="person-transfer-to"
        value={to}
        placeholder="sheet id"
        onChange={(e) => {
          setTo(e.target.value);
          setError('');
        }}
      />{' '}
      <button type="button" data-testid="person-transfer" onClick={submit} disabled={transfer.isPending}>
        Transfer
      </button>
      {error && (
        <p role="alert" data-testid="person-error">
          {error}
        </p>
      )}
    </td>
  );
}

export const contributions = [
  PersonHead.fill({ order: 64, Component: OriginHead }),
  PersonRow.fill({ order: 64, Component: PersonOrigin }),
  PersonHead.fill({ order: 66, Component: TransferHead }),
  PersonRow.fill({ order: 66, Component: PersonTransfer }),
];

