package net.officefloor.hq.app.sheet;

import jakarta.servlet.http.HttpServletRequest;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.plugin.variable.Val;

/**
 * Records the clone on this sheet, then the clone's first lines: where it was cloned from, followed by
 * its rollup lines for every person and its totals. Runs after every rule has passed, so a refused
 * clone writes nothing.
 */
public class AuditSheetCloned {
    public void audit(@Val Sheet sheet, @Val Clone clone, PersonRepository people, ClaimRepository claims,
            RateRepository rates, SettingsRepository settings, HttpServletRequest request, Audit audit) {
        String user = Audit.user(request);
        String to = clone.to().id();
        audit.record("SHEET_CLONE_MADE sheet=" + sheet.id() + " by=" + user + " to=" + to);
        audit.record("SHEET_CLONED sheet=" + to + " by=" + user + " from=" + sheet.id());
        Rollup none = new Rollup(Map.of(), "", "", "");
        Rollup.of(to, clone.to().today(), people, claims, rates, settings.find(to))
                .changesSince(none, to, user).forEach(audit::record);
    }
}
EOF
cat > RespondWithClone.java <<'EOF'
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClone {
    public void respond(@Val Clone clone, ObjectResponse<CloneResponse> response) {
        response.send(new CloneResponse(clone.to().id()));
    }
}
EOF
cat > "../../../../../../resources/officefloor/rest/api/sheets/{sheetId}/clone.POST.yml" <<'EOF'
# Clone the sheet to another id (a steward). Validate first so a blank id is a 400, not a 404. Anyone
# else, or an id already used, is refused and writes nothing.
validate:
  class: net.officefloor.hq.app.sheet.ValidateClone
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: clone
clone:
  class: net.officefloor.hq.app.sheet.CloneSheet
  govern: [ transaction ]
  next: audit
# Last before the response: the clone is saved. This sheet's line, then the clone's first lines.
audit:
  class: net.officefloor.hq.app.sheet.AuditSheetCloned
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithClone
  govern: [ transaction ]
EOF

